CREATE OR REPLACE FUNCTION public.admin_unit_timeline(_unit uuid,_limit integer DEFAULT 25,_offset integer DEFAULT 0) RETURNS jsonb LANGUAGE sql SECURITY INVOKER SET search_path=public AS $$ WITH events AS (SELECT h.id,h.at AS occurred_at,jsonb_build_object('id',h.id,'at',h.at,'actor_role',h.actor_role,'action','UNIT_STATUS_TRANSITION','from_status',h.from_status,'to_status',h.to_status,'reason',h.reason,'ref_type',h.ref_type,'ref_id',h.ref_id) AS event FROM public.unit_status_history h WHERE h.unit_id=_unit UNION ALL SELECT a.id,a.created_at,to_jsonb(a) FROM public.audit_log a WHERE a.entity_table='units' AND a.entity_id=_unit::text AND NOT EXISTS (SELECT 1 FROM public.unit_status_history h WHERE h.unit_id=_unit AND a.action='UNIT_STATUS_TRANSITION' AND a.context->>'ref_type'=h.ref_type AND a.context->>'ref_id'=h.ref_id::text AND a.after_data->>'leasing_status'=h.to_status::text AND a.actor_id IS NOT DISTINCT FROM h.actor AND abs(extract(epoch FROM a.created_at-h.at))<0.01)), paged AS (SELECT event FROM events ORDER BY occurred_at DESC,id LIMIT least(greatest(_limit,1),100) OFFSET greatest(_offset,0)) SELECT jsonb_build_object('rows',coalesce((SELECT jsonb_agg(event) FROM paged),'[]'::jsonb),'count',(SELECT count(*) FROM events)); $$;
REVOKE ALL ON FUNCTION public.admin_unit_timeline(uuid,integer,integer) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_unit_timeline(uuid,integer,integer) TO authenticated;
SELECT to_regprocedure('public.admin_unit_timeline(uuid,integer,integer)') IS NOT NULL AS timeline_ready;